def C(n,lesson,title,pages,scenario,columns,raw,code='',notes=None,assumptions=None,kind='table'):
 l=lessons[lesson-1];ch='ABCD'.index(l['topic'])+1
 c=dict(id=f'SC{n:02}',topic=l['topic'],title=title,scenario=scenario,unit='표의 한 행은 '+({'flow':'메시지 또는 처리 단계','code':'설정·입력·결과 항목'}.get(kind,'관찰·정책 항목')),validN=len(raw),exclusions='표에 명시하지 않은 트래픽·계정·정책은 포함하지 않습니다.',assumptions=assumptions or ['모든 수치·주소·계정·조직은 학습용 가상 자료입니다.','표의 결과는 제시한 조건에만 해당하며 실제 시스템 안전을 보장하지 않습니다.'],synthetic=True,numericOrigin='강의 개념을 적용하도록 직접 설계한 가상 사례입니다. 교재 연습문제 원문이 아닙니다.',columns=columns,rows=[dict(zip(columns,r)) for r in raw],code=code,codeNotes=notes or [],guide=[scenario,'표의 각 열과 코드의 입력·출력 위치를 확인하세요.',(assumptions or ['표 밖의 정책과 트래픽은 알 수 없습니다.'])[0],'연결된 강의에서 해당 검사·규칙의 순서를 확인하세요.','관찰 결과가 없는 원인·신원·공격 성공은 추가 증거 없이는 단정하지 않습니다.'],lessonId=l['id'],sources=ref(ch,pages),supplements=[],questionIds=[],kind=kind)
 cases.append(c);l['caseIds'].append(c['id']);return c
def Q(c,kind,stem,answer,detail,alternatives=None,calc=None,unit='개',steps=None,rubric=None):
 i=len(c['questionIds'])+1;id=f"SQ{c['id'][2:]}-{i}";c['questionIds'].append(id)
 q=dict(id=id,caseId=c['id'],topic=c['topic'],kind=kind,difficulty='보통' if kind!='essay' else '심화',skill='코드 읽기' if c['kind']=='code' else '흐름 해석' if c['kind']=='flow' else '조건 판단',mistake='계산' if kind=='numeric' else '개념',stem=stem,explanation=detail,steps=steps or [stem,'제시한 조건과 자료를 대조합니다.',detail],commonError=(alternatives or [('','제시한 범위를 넘어 결론내리지 않습니다.')])[0][1],lessonId=c['lessonId'],sources=c['sources'],origin='직접 작성한 예상 연습문제')
 if kind=='choice':
  opts=[(answer,detail)]+alternatives;q['choices']=[dict(id=f'{id}-O{j+1}',text=a,reason=r) for j,(a,r) in enumerate(opts)];q['correctId']=q['choices'][0]['id']
 elif kind=='numeric':q['numeric']=dict(value=answer,tolerance=0,unit=unit,rounding='정확한 정수. 숫자만 입력. 허용 오차 0.',calculation=calc)
 elif kind=='short':q['accepted']=answer if isinstance(answer,list) else [answer];q['modelAnswer']=q['accepted'][0]
 else:q['modelAnswer']=answer;q['rubric']=rubric or [answer,detail,'사례의 조건과 대응의 한계를 설명했다.']
 questions.append(q);return q
def choice(c,s,a,d,*alts):return Q(c,'choice',s,a,d,list(alts))
def short(c,s,a,d):return Q(c,'short',s,a,d)
def essay(c,s,a,d,rubric=None):return Q(c,'essay',s,a,d,rubric=rubric)
def number(c,s,a,d,calc,unit='개',steps=None):return Q(c,'numeric',s,a,d,calc=calc,unit=unit,steps=steps)

